const d=[{id:"meaning-frankl",title:"M17 · Viktor Frankl Institute of America · Logoterapi açısından anlam",url:"https://viktorfranklamerica.com/meaning-from-a-logotherapy-perspective/",type:"guidance",finding:"Frankl, anlam bulmanın yollarını bir şey üretmek veya yapmak, bir deneyim yaşamak veya sevmek ve kaçınılmaz acı karşısında isteğe bağlı bir tutum seçmek olarak anlattı.",limitation:"Felsefi ve klinik bir açıklama, deney değil. Acı çekmek şart değil. Bu düşünme çalışması tedavi etkisini göstermez."},{id:"meaning-frankl-history",title:"M18 · Viktor Frankl Institute Vienna · Biyografi",url:"https://www.viktorfrankl.org/biography.html",type:"guidance",finding:"Frankl logoterapiyi Naziler tarafından hapsedilmeden önce geliştirdi. Enstitünün biyografisi hayatını ve çalışmalarını anlatır.",limitation:"Tarihsel yaşantı, psikolojik uygulamanın etkisini göstermez. Acıda anlam bulmanı zorunlu kılmaz."},{id:"meaning-act-values",title:"M19 · Association for Contextual Behavioral Science · ACT’nin altı temel süreci",url:"https://contextualscience.org/six_core_processes_act",type:"guidance",finding:"ACT’de değerler, sürdürdüğün davranışların özellikleridir. Kararlı eylem bunları somut hedeflerle birleştirir.",limitation:"Uzmanlara yönelik model rehberi, deney değil. ODA pusulası ve kısa işleri birer uyarlamadır. Doğrulanmış puan veya bağımsız etki yok."},{id:"meaning-act-trials",title:"M04 · A-Tjak ve arkadaşları · 2015 · ACT meta-analizi",url:"https://doi.org/10.1159/000365764",type:"research",finding:"Klinik açıdan önemli ruhsal veya fiziksel sorunları olan 1.821 kişiyle 39 randomize araştırma, tam ACT programlarını sınadı.",limitation:"Klinik programın bütününe ait kanıt, değerler formunu tek başına sınamaz, kursu doğrulamaz veya yerleşik BDT’ye üstünlük göstermez."},{id:"meaning-sdt",title:"M05 · Ryan ve Deci · 2000 · Öz belirleme kuramı",url:"https://selfdeterminationtheory.org/SDT/documents/2000_RyanDeci_SDT.pdf",type:"research",finding:"Kuram, kişinin benimsediği nedenle davranmasını baskıdan ayırır. Dışarıdan gelen bazı sorumluluklar kişinin benimsediği sorumluluklara dönüşebilir.",limitation:"Kuram makalesi, nedenleri ölçen test değil. Suçluluk, keyif, bedensel enerji ve başkalarının fark etmesi, bir değerin sana ait olup olmadığını belirlemez."},{id:"meaning-sdt-interventions",title:"M06 · Ntoumanis ve arkadaşları · 2021 · Sağlıkta motivasyon çalışmaları",url:"https://eprints.whiterose.ac.uk/id/eprint/155741/",type:"research",finding:"30.088 kişiyi kapsayan 73 sağlık çalışması, benimsediği nedenlerle davranmada ve sağlık davranışında ortalama iyileşmeler buldu. Etkiler farklıydı.",limitation:"58 randomize ve 15 yarı deneysel araştırma, farklı destek programları kullandı. Kısa değerler formu, araştırmada sınanan uygulama değildir."},{id:"meaning-support",title:"M20 · NIMH · Depresyon",url:"https://www.nimh.nih.gov/health/publications/depression",type:"guidance",finding:"Süren çökkünlük, umutsuzluk, ilgi kaybı veya günlük işleri yapmakta güçlük, uzman değerlendirmesi ve destek gerektirir. ABD’de 988 üzerinden kriz desteği alınabilir.",limitation:"Tek başına anlam kaybı depresyon tanısı koydurmaz. ODA eğitim desteğidir. Depresyonu tedavi edemez veya akut krizi yönetemez."},{id:"meaning-carrillo",title:"M09 · Carrillo ve arkadaşları · 2019 · Best Possible Self meta-analizi",url:"https://journals.plos.org/plosone/article?id=10.1371/journal.pone.0222386",type:"research",finding:"2.909 kişiyi kapsayan 29 araştırma, iyi oluşta, olumlu duygularda ve iyimserlikte ortalama iyileşmeleri destekledi. Olumsuz duygu ve depresyondaki azalmalar gösterilmedi.",limitation:"Olumsuz duygular ve depresyon için hesaplanan iki güven aralığı da sıfırı içeriyordu. Depresyonu yalnızca üç araştırma ölçtü. Yöntemler farklı, sonuçlar çoğunlukla kısa vadeli. Anlam veya gelecekte gerçek başarı gösterilmedi."},{id:"meaning-best-possible-self",title:"M10 · King · 2001 · Hayat hedefleri hakkında yazmak",url:"https://doi.org/10.1177/0146167201277003",type:"research",finding:"81 üniversite öğrencisi dört yazma koşuluna rastgele atandı. Geleceği yazma görevi, art arda dört gün, her gün 20 dakika sürdü.",limitation:"İlk görev, ODA’nın kısa ve değerlerine bağlı uyarlamasını sınamadı. Daha çok anlam, hastalığı önleme veya geleceğin gerçekten gerçekleşmesi gösterilmedi."},{id:"meaning-planning",title:"M11 · Gollwitzer ve Sheeran · 2006 · Belirli durumda yapılacak işi planlamak",url:"https://doi.org/10.1016/S0065-2601(06)38002-1",type:"research",finding:"8.461 kişiyi kapsayan 94 bağımsız test, belirli durumu istenen yanıtla birleştiren planların hedefe ulaşmaya ortalama faydasını destekledi.",limitation:"Deneysel ve ilişkisel testler birlikteydi. Koşullar farklıydı. Plan yapmak iş yapmak değildir. Derleme, anlam artışını veya ODA’nın bu birleşik akışını doğrulamadı."},{id:"meaning-mental-contrasting",title:"M13 · Wang, Wang ve Gai · 2021 · Zihinsel karşılaştırma ve planlama",url:"https://www.frontiersin.org/articles/10.3389/fpsyg.2021.565202/pdf",type:"research",finding:"21 makaleden, 15.907 kişiyi kapsayan 24 bağımsız araştırma, hedefe ulaşmada küçük ortalama etki buldu: g = 0,336 [0,229; 0,443].",limitation:"Yayın yanlılığı ve uygulama farkları kesinliği sınırlar. Değerler, gelecek sahnesi ve işten oluşan birleşik uyarlama sınanmadı. Yapısal engeller kişisel başarısızlık değildir."},{id:"meaning-monitoring",title:"M14 · Harkin ve arkadaşları · 2016 · İlerlemeyi takip etmek",url:"https://eprints.whiterose.ac.uk/id/eprint/87431/1/bul%20harkin%20raw%20final.pdf",type:"research",finding:"138 randomize araştırmada takibi artırmak, hedefe ulaşmaya ortalama fayda sağladı: d = 0,40 [0,32; 0,48].",limitation:"Küçük araştırmalarda asimetri bulundu. Duyarlılık analizi d = 0,19 tahmin etti. Hedef ve yöntem farkları, ODA’nın ertesi gün zamanlamasını, anlam etkisini veya zorunlu açık takibi doğrulamaz."},{id:"meaning-habits",title:"M15 · Lally ve arkadaşları · 2010 · Alışkanlık oluşumu",url:"https://doi.org/10.1002/ejsp.674",type:"research",finding:"84 günlük gözlem araştırması 96 kişiyi takip etti. Modellenen otomatikleşme farklı hızlarda arttı. Tek fırsatı kaçırmanın ölçülen etkisi azdı.",limitation:"Sık anılan 66 gün ortancası ve 18–254 gün aralığı model tahminleridir. Uzun değerler gözlemden ileriye uzatılır. Son tarih, tekrarlayan aralar veya değerlerin otomatikleşmesi hakkında kanıt değildir."}],k=[{schemaVersion:2,revision:2,id:"meaning-1",courseId:"meaning",locale:"tr",title:"Hafta doldu. Önemsediğin şeye sıra geldi mi?",goal:"Seçtiğin bir ilişki veya katkı için bugün işe yarayan küçük bir adım at.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"İş, ev işleri, telefonda gezinmek... Bir hafta daha mı geçti? Önemsediğin tek bir şeye bugün sıra ver.",reason:{id:"meaning-1-reason-attention-cost",label:"Bu amaca iki dakika ayırmak için isteğe bağlı hangi işi sonraya bırakabilirsin?",kind:"text",maxLength:160,optional:!0,suggestions:["Telefonda gezinmeyi sonraya bırakmak","Acil olmayan ev işini ertelemek","Kısa bir konuşmaya zaman ayırmak"]},why:{id:"meaning-1-why",label:"Bu hafta hangi şeye dikkatini ayıracak kadar önem veriyorsun?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Önemsediğin bir şeyi yapmak için önce hayatının büyük amacını bulman gerekmiyor. Frankl’ın felsefesi birkaç olası yol anlatır: üretmek veya yapmak, deneyimlemek veya sevmek, kaçınılmaz zorluk karşısında bir tutum seçmek. Bunlar düşünmek için sorular. Bir sınav veya kanıtlanmış tedavi değil. Zorluk konusunu tamamen dışarıda bırakabilirsin.","Kurs boyunca denemek için katkı sağlayacağın bir işi veya bir ilişkiyi seç. Küçük bir adım atabileceğin gerçek bir fırsat bul, sonra olanı kaydet. Soruyu sorup yanıtı dinlemek bir iş yapmaktır. Kimlerin önemli olduğunu listelemek hazırlıktır. Ruh hâlin aynı kalabilir. Burada gerçekten ne yaptığına bakıyoruz."],example:{title:"Murat akşam yemeğinde soruyor",text:"Salı akşamı yemekte Murat, kızını bütün hafta neredeyse hiç dinlemediğini fark ediyor. Telefonunu kaldırıp fen projesini soruyor. Yanıtı dinliyor. Kızı çıkmadan önce yalnızca iki kısa cümle söylüyor. Murat soruyu sorduğunu ve dikkatini verdiğini kaydediyor. Konuşma kısa sürdü, ama oldu. Kızının uzun uzun anlatması, Murat’ın seçtiği dinleme adımını yapmış olması için şart değil."}},move:{invitation:"Seçtiğin ilişki veya katkı için işe yarayan tek bir adım at.",instructions:["Kurs boyunca sürdüreceğin tek bir amaç seç.","Küçük bir işi yap, sonra gerçekte ne olduğunu kaydet."],prompts:[],suggestions:{action:["Telefona bakmadan bir soru sor ve dinle","Proje için işe yarayan tek cümleyi tamamla","Belirli bir konuda yardım etmeyi teklif et"],minimum:["Tek bir soru sorup yanıtını dinle","Kullanılabilecek tek bir cümle yaz","Belirli tek bir yardım teklifinde bulun"],cue:["Akşam yemeğinden sonra birlikte oturduğumuzda","Projemi açıp başına geçtiğimde","Sıradaki güvenli görüşmemiz başladığında"],place:["Mutfaktaki masamızda","Her zamanki çalışma yerimde","Güvenle konuşabildiğim mesaj grubumuzda"],minutes:[2,5],fallback:["Güvenli bir sesli veya yazılı mesaj kullan","Başka bir uygun konuşma fırsatını seç","Birinden pratik destek iste"],observation:["Ne sorduğum ve ne duyduğum","Yazdığım işe yarayan cümle","Yardım teklifini gerçekten iletip iletmediğim"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"Telefona bakmadan bir soru sor ve dinle",minimum:"Tek bir soru sorup yanıtını dinle",minutes:2,cueHint:"Akşam yemeğinden sonra birlikte oturduğumuzda",placeHint:"Mutfaktaki masamızda",obstacleHint:"Karşı taraf uygun değil veya benim dikkatim dağılıyor.",fallbackHint:"Güvenli bir sesli veya yazılı mesaj kullan",observationHint:"Ne sorduğum ve ne duyduğum"},stopRule:"Güvenli ve karşı tarafın da istediği bir görüşme seç. Yardım, imkânlarına ve sınırlarına uysun.",accessibleAlternative:"Her zamanki iletişim yöntemini kullanabilir, yardım alarak katkıda bulunabilir veya kimseyle paylaşmadan yaratıcı bir iş yapabilirsin."},result:{question:"Seçtiğin işi gerçekten yaptın mı?",observationPrompt:"Neye katkı sağladın, ne sordun veya ne duydun?"},judgment:{primary:{id:"meaning-1-dinner-opening-decision",scenario:"Murat bu akşam kızının projesini dinlemeyi seçmiş. Kızının çıkmadan önce beş dakikası var. Bulaşıklar bekleyebilir. Murat bir de işe yarayan soru hazırlamak istiyor.",question:"Bu fırsatı hangi seçim kendi amacına uygun kullanır?",options:[{id:"listen-now",text:"Projesini şimdi sorup yanıtını dinlemek, ardından gerçekten neler olduğunu kısa bir notla kaydetmek.",feedback:"Seçtiği dikkatli konuşma için fırsatı kullanır. Yanıt kısa veya dalgın olabilir. Bulaşıklar ve ek hazırlık bekleyebilir. Bu örnek herkes için ilişkinin ilk sırada gelmesi gerektiğini söylemez; Murat’ın seçimine dayanır."},{id:"meaning-1-share-chore",text:"Beş dakika boyunca birlikte bulaşık yıkarken masayı toplamak ve aynı anda projenin nasıl gittiğini sormak.",feedback:"Ortak ev işi yakınlığa katkı sağlayabilir. Burada Murat dikkatini vererek dinlemeyi seçti ve bulaşıklar bekleyebilir. İkisi de ortak işi tercih etmiyorsa dikkatini bölmek yerine kısa konuşmayı korusun."},{id:"meaning-1-prepare-question",text:"Beş dakikayı proje hakkında iyi bir soru hazırlamaya ayırıp kızı evden çıktıktan sonra mesaj göndermek.",feedback:"Soru hazırlamak sonraki konuşmayı kolaylaştırabilir. Burada kızı uygun ve konu zaten belli. Şimdi sor. Kızı konuşmak istemezse bunu “Fırsat olmadı” olarak kaydet. Hazırlığı görüşmenin yerine koymak gerekmiyor."}],bestOptionId:"listen-now"}},carry:{takeaway:"Önemsediğin şeye sıra ver. Sonra ne yaptığını ve ne olduğunu kaydet.",followUp:{questionId:"meaning-1-return",question:"Seçtiğin fırsat geldiğinde gerçekte ne oldu, ne yaptın?",observationPrompt:"Hangi işi yaptın? O fırsat gerçekten var mıydı, yoksa oluşmadı mı?",adjustmentPrompt:"Sonraki fırsat için neyi ertelemen veya değiştirmen gerekiyor?"}},goDeeper:{sections:[{heading:"Birden fazla yol gösteren bir felsefe",paragraphs:["Frankl’ın üç yolu, herkesin tamamlaması gereken bir listeden gelmiyor. Felsefi ve klinik bir açıklamanın parçaları. Üretmek, yararlı bir iş veya bir davranış olabilir. Deneyimlemek, güzelliği fark etmek veya bir ilişkiye dikkat vermek olabilir. Kaçınılmaz acı karşısındaki tutum ise başka bir ihtimal. Zorunluluk değil. Acını anlatmadan katkıyı veya ilişkiyi seçebilirsin. Frankl’ın Amerika’daki enstitüsünün açıklaması bu yolları anlatır. [M17]","Viyana’daki enstitünün biyografisi, Frankl’ın logoterapiyi Naziler tarafından hapsedilmeden önce geliştirmeye başladığını gösterir. [M18] Sonradan yaşadıkları hayatının tarihine aittir. Kısa dersin sıkıntıyı tedavi ettiğinin kanıtı değildir. Bu kurs felsefeden sorular alır, cevabı sana bırakır. Büyük bir yanıt bulamasan da küçük bir iş seçebilirsin. Dikkatli bir soru, yararlı bir paragraf veya sınırları belirli yardım teklifi, amacını gözleyebileceğin bir işe dönüştürür."]},{heading:"Fark etmekten gerçek bir fırsata",paragraphs:["Anlamlı görünen bir planla yaptığın işi ayrı ayrı kaydet. Planlama araştırmaları, ne zaman başlayacağını ve ne yapacağını belirlemeyi destekler: fark edebileceğin durum oluştuğunda, seçtiğin işi yap. Gollwitzer ve Sheeran, 8.461 kişiyi kapsayan 94 bağımsız testi birleştirdi. [M11] Hedefe ulaşmak ortalama olarak iyileşti. Ama katılımcılar, hedefler ve araştırma biçimleri farklıydı. Bu sonuç, planın anlam duygusunu artırdığını veya kursun felsefe ile işi birleştiren akışının etkili olduğunu göstermez. İki iddiayı ayrı tut.","ODA uyarlamasında tek bir amaç, iş ve yapılabilir küçük adım seçersin. İlk iş amacınla ilgili olsun. Tek yanıtı dinlemek ilişkiye katkı verir. Yalnızca kişi listesini açmak hazırlıktır. Fırsat yoksa “Fırsat olmadı”, gelecekteki görüşme içinse “Planlandı” olarak kaydet. Konuşmanın hayatını değiştirdiğini kanıtlamak gerekmiyor. Pratik değeri sonraki seçimin için bilgi vermesi. Başka ortam, destek veya başka amaç sana daha iyi uyabilir. Duygunun değişmemesi, görüşmenin yapılmadığı anlamına gelmez."]}],sourceIds:["meaning-frankl","meaning-frankl-history","meaning-planning"]}},{schemaVersion:2,revision:2,id:"meaning-2",courseId:"meaning",locale:"tr",title:"Önemli dediğin şeye hep kalan zaman mı?",goal:"Seçtiğin amaç için küçük bir işe zaman ayır. Bunun için neyin beklemesi gerektiğini açıkça söyle.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Önemli diyorsun. Ona zaman ayırıyor musun, yoksa bütün işlerden artan dakikaları mı bırakıyorsun?",reason:{id:"meaning-2-reason",label:"Bu amaca zaman ayırmak için hangi işi başka zamana taşıyacaksın?",kind:"text",maxLength:160,optional:!0,suggestions:["Telefonda gezinmeyi başka zamana taşımak","Daha küçük bir sözü tutmak","Özenli çalışmaya yer açmak"]},why:{id:"meaning-2-why",label:"Bu amaca zaman ayırmak için hangi işi başka zamana taşıyacaksın?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Hedef, pazar günü birini ziyaret etmek gibi bitirebileceğin bir şey. Değer ise dikkatini vermek gibi sürdürmek istediğin bir davranma biçimi. Bu ayrım bir terapi modelinden gelir. Hedeflerin daha önemsiz olduğunu söylemez. Bir yere varamamış olman, hangi yönde ilerlemek istediğini tek başına belirlemez. İkisi birlikte sana yol gösterebilir.","Aynı amacı ve aynı işi denemeyi sürdür. Önündeki uygun zamana bak. Değer verdiğin iki şey aynı zamanı isteyebilir. İşe yarayan küçük adımı seç, neyin bekleyeceğini söyle. Burada bir seçim yapıyorsun. Diğer değer ortadan kalkmıyor. Seçimin işe yarayıp yaramadığını değerlendirmeden önce o işi gerçekten yap ve sonra gözle."],example:{title:"Murat konuşmaya yer açıyor",text:"Çarşamba Murat’ın evdeki bir işten önce on dakikası var. Hem yeniden konuşmak hem okumak istiyor. Kızının projesine iki dakika ayırıp ev işine başlıyor. Okuma perşembeye kalıyor. Kızı dalgın görünüyor. Murat bunu da kaydediyor. Her şeyi aynı zamana sıkıştırmak yerine sınırları belli bir iş seçti. Konuşmanın istediği gibi geçmesi, seçtiği adımı yapmasının şartı değildi."}},move:{invitation:"Amacını koru. Sonraki küçük işe ayırabileceğin bir zaman seç.",instructions:["Aynı zamanı isteyen başka tek bir işi belirt.","İşe yarayan en küçük adımı seçip gerçekten yap."],prompts:[],suggestions:{action:["Ayırdığım zamanda soru sorup yanıtını dinle","Proje için işe yarayan tek cümle yaz","Kapsamı belli bir bakım işini tamamla"],minimum:["Tek bir yanıtı dikkatimi vererek dinle","Kullanılabilecek tek bir cümle yaz","Anlaştığımız küçük işlerden tek birini tamamla"],cue:["Akşam yemeğinden sonra birlikte oturduğumuzda","Projeme ayırdığım zaman geldiğinde","Mevcut bakım işini tamamladıktan sonra"],place:["Mutfaktaki masamızda","Her zamanki çalışma yerimde","İşin gerçekten yapılması gereken yerde"],minutes:[2,5],fallback:["Daha kısa bir konuşma fırsatını kullan","İşi küçült, işe yarayan kısmını yap","Sorumluluğu paylaşmak için yardım iste"],observation:["Yaptığım iş ve beklettiğim diğer iş","Gerçekte ne kadar zaman ayırdığım","Küçük adımın amacıma katkı sağlayıp sağlamadığı"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"Ayırdığım zamanda soru sorup yanıtını dinle",minimum:"Tek bir yanıtı dikkatimi vererek dinle",minutes:2,cueHint:"Akşam yemeğinden sonra birlikte oturduğumuzda",placeHint:"Mutfaktaki masamızda",obstacleHint:"Değer verdiğim iki sorumluluk aynı zamanı istiyor.",fallbackHint:"Daha kısa bir konuşma fırsatını kullan",observationHint:"Yaptığım iş ve beklettiğim diğer iş"},stopRule:"Acil bakımın veya gereken dinlenmenin zamanından alma. İşin zamanını ya da boyutunu değiştir.",accessibleAlternative:"Aynı amacı korumak için iletişim desteği, oturarak yapılacak bir iş veya birinden yardım seçebilirsin."},result:{question:"Zaman ayırdığın en küçük adımı gerçekten yaptın mı?",observationPrompt:"Gerçekte ne yaptın? Hangi işi daha sonraya bıraktın?"},judgment:{primary:{id:"meaning-2-chosen-commitment-decision",scenario:"Murat, kızı yolculuğa çıkmadan dikkatli bir konuşma sözü vermiş. Bu akşamki on dakika son fırsat. Acil olmayan kitabının bölümünü bitirmeye de önem veriyor. Uzun bir telefon görüşmesi gelecek haftaya kalabilir.",question:"Hangi seçim verdiği sözü bu zamana sığdırır?",options:[{id:"reading-later",text:"Zamanın sınırlı olduğunu kabul edip şimdi kısaca dinlemek, okumak için başka bir zaman seçmek.",feedback:"Bu akşam fırsat varken seçtiği konuşmayı korur. Okumak hâlâ önemli ve başka zamana yerleşebilir. Kararı belirleyen, verdiği söz ve zamanlama. Bir değerin diğerinden daha üstün olması değil."},{id:"full-both",text:"Önemli iki sözden hiçbiri beklemesin diye kızını dinlerken bir yandan kitabının bölümünü bitirmeye çalışmak.",feedback:"İşleri birleştirmek okuma zamanını koruyabilir. Ama söz verdiği dikkati böler. İki tam işi sığmış saymak yerine şimdi kısa dinleme adımını yap, okumayı başka zamana taşı. Seçimin bedelini açık tut."},{id:"meaning-2-next-week-call",text:"Her işe ayrı zaman ayırmak için bu akşam okuyup gelecek haftaya daha uzun bir konuşma planlamak.",feedback:"Ayrı zamanlar mantıklı olabilir; uzun görüşme de değerli olabilir. Ama yolculuk öncesi seçtiği konuşma kaçmış olur. Küçük sözü şimdi tut. Daha uzun bir görüşmeyi ayrıca planlayabilirsin."}],bestOptionId:"reading-later"}},carry:{takeaway:"Hedefini kaçırınca istediğin yön kaybolmaz. Bugün ona katkı sağlayan yapılabilir tek bir iş seç.",followUp:{questionId:"meaning-2-return",question:"Ayırdığın zaman seçtiğin amaca katkı sağladı mı? Gerçekte nasıl kullandın?",observationPrompt:"Küçük adım amacına katkı sağladı mı? Hangi başka iş bunun için bekledi?",adjustmentPrompt:"Bu seçimi koruyacak mısın, yoksa zamanını veya işin boyutunu mu değiştireceksin?"}},goDeeper:{sections:[{heading:"Yön ve varış noktası farklı işler görür",paragraphs:["Association for Contextual Behavioral Science, değerleri süren davranışların seçilmiş özellikleri olarak anlatır. Kararlı eylem bunları somut hedeflerle birleştirir. [M19] Dikkat vermek bir yön. Bu akşam tek yanıtı dinlemek bitebilen bir iş. Birlikte çalışırlar. İşi bitirirsin, dikkat vermeyi bitirmiş olmazsın. Hedefini değiştirirken yönünü koruyabilirsin. Bu ayrımlar Kabul ve Kararlılık Terapisi, yani ACT modeli içindedir. Deneylerle bulunmuş, herkese zorunlu evrensel kategoriler değildir.","ODA’nın pusulası bir eğitim uyarlaması: hayatının bir alanını seç, nasıl davranmak istediğini söyle, koşullarına bak ve yapabileceğin işi belirle. Doğrulanmış puan eşiği yok. Her alanı puanlamak veya en büyük sayısal farkı kapatmak gerekmiyor. Bakım sorumluluğu, azalan güç veya değişmeyen vardiyası olan biri önce sürdürebileceği bir düzeni seçebilir. Pusulayı hayatına hüküm vermek için kullanma. Bu haftanın gerçek koşullarına göre neye sıra vereceğini belirle."]},{heading:"Kısa adım, tedavi programının bütünü değil",paragraphs:["A-Tjak ve arkadaşları, klinik açıdan önemli ruhsal veya fiziksel sorunları olan 1.821 kişiyle 39 randomize araştırmayı inceledi. [M04] Araştırmalar, farklı durumlarda ve farklı karşılaştırmalarla tam Kabul ve Kararlılık Terapisi programlarını sınadı. Değerler pusulasını tek başına sınamadı. Bu formun etkisini göstermedi veya ODA’nın terapi sunduğunu doğrulamadı. Bir yöntem, bütün programın klinik kanıtını üstlenmeden de seçim yapmana yol gösterebilir. Yardım edici fikirle kanıtlanmış tedavi ayrı şeyler.","Zaman ayırma kısmı, belirli durumda belirli yanıtı planlama araştırmalarından ayrıca destek alır. [M11] Akşam yemeğinden sonra oturmak, “Bu hafta bir ara”dan daha tanınabilir bir an. Kanıt, hedefe ulaşmayla ilgili; hayatından memnun hissetmekle değil. Küçük adım anlamlı, seçimin bedeli açık kalsın. Acil olmayan işi ertelersen başka zamanını söyle. Gerekli bakım veya toparlanma tehlikeye giriyorsa adımı küçült, yardım al ya da başka uygun bir fırsat seç."]}],sourceIds:["meaning-act-values","meaning-act-trials","meaning-planning"]}},{schemaVersion:2,revision:2,id:"meaning-3",courseId:"meaning",locale:"tr",title:"Kendi seçimin de zor gelebilir",goal:"Benimsediğin bir nedenle küçük bir iş yap. Sorumluluklarını ve uyman gereken koşulları koru.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Önemsediğin bir seçim yüzünden hâlâ suçluluk mu duyuyorsun? Bu duygu, seçimin sana ait olup olmadığına karar vermez.",reason:{id:"meaning-3-reason",label:"Hangi nedeni benimsiyorsun? Hangi sorumluluğunu koruman gerekiyor?",kind:"text",maxLength:160,optional:!0,suggestions:["Sevdiğim insanlara özen göstermek","Maddi sorumluluklarımı korumak","İsteğe bağlı tek bir işi seçmek"]},why:{id:"meaning-3-why",label:"Hangi nedeni benimsiyorsun? Hangi sorumluluğunu koruman gerekiyor?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Ailenden öğrendiğin sorumluluğu sen de benimseyebilirsin. Motivasyon araştırmaları, benimsediğin nedenlerle davranmayı baskı altında davranmaktan ayırır. Ama bir seçimin sana ait olduğunu hemen gösteren test sunmaz. Suçluluk, yorgunluk veya memnuniyet yaşantın hakkında bir şey söyler. Bir değerin sana ait olup olmadığını tek başına belirlemez. Nereden geldiğine bakmak, kararın tamamı değildir.","Denediğin aynı amaca bak. Hâlâ benimsediğin bir nedeni ve uyman gereken bir koşulu söyle. Temel sorumluluklarını koru. Bedeli düşük, isteğe bağlı tek seçimi değiştir; sonra yararlı işi yap. Birden fazla nedenin olabilir. Önce hepsinden kesin emin olman gerekmiyor. Rahatsızlık sürerken de sorumluluklarına uyan bilinçli bir seçim yapabilirsin."],example:{title:"Murat benimsediği nedene göre davranıyor",text:"Perşembe mutfak masasında Murat, isteğe bağlı iş sohbetine katılmadığı için suçlu hissediyor. Kızıyla ilgilenmeyi hâlâ istiyor; zorunlu vardiyasını da koruyor. İki dakikalık konuşmalarında kızının maketini sorup yanıtını dinliyor. Konuşmayı ve huzursuzluğunu kaydediyor. Suçluluk sürerken de kendi nedenini benimsedi. Sırf rahat hissetmediği için bu seçimin ona ait olmadığını söylemesi gerekmiyor."}},move:{invitation:"Benimsediğin nedenle, daha önce denediğin aynı küçük adımı at.",instructions:["Gerekli sorumlulukları koru. İsteğe bağlı hangi işi erteleyeceğini söyle.","Duygunun kesinleşmesini beklemeden seçtiğin işi gerçekten yap."],prompts:[],suggestions:{action:["Benimsediğim nedenle bir soru sorup dinle","İsteğe bağlı projeye tek bir katkı yap","Başka işle çakışan isteğe bağlı daveti reddet"],minimum:["Tek bir yanıtı dikkatimi vererek dinle","İşe yarayan tek bir cümle yaz","Ne zaman uygun olduğumla ilgili sınırı söyle"],cue:["Akşam yemeğinden sonra birlikte oturduğumuzda","İsteğe bağlı projeme ayırdığım zaman geldiğinde","İsteğe bağlı davet bana ulaştığında"],place:["Mutfaktaki masamızda","Her zamanki çalışma yerimde","Güvenle konuşabildiğim mesaj grubumuzda"],minutes:[2,5],fallback:["Gerekli sorumlulukları koru, bu işi küçült","İsteğe bağlı seçeneklerden bedeli daha düşük olanı seç","Uymam gereken koşul için destek iste"],observation:["Karışık duygularıma rağmen hangi seçimi yaptığım","Hangi nedeni hâlâ benimsediğim","Hangi gerekli sorumluluğu koruduğum"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"Benimsediğim nedenle bir soru sorup dinle",minimum:"Tek bir yanıtı dikkatimi vererek dinle",minutes:2,cueHint:"Akşam yemeğinden sonra birlikte oturduğumuzda",placeHint:"Mutfaktaki masamızda",obstacleHint:"Baskı hissediyorum. Bazı sorumluluklarımı bırakamam.",fallbackHint:"Gerekli sorumlulukları koru, bu işi küçült",observationHint:"Karışık duygularıma rağmen hangi seçimi yaptığım"},stopRule:"Geri dönüşü olmayan değişikliklerden kaçın. Gerekli geliri, bakımı, güvenliği ve ihtiyaç duyduğun desteği koru.",accessibleAlternative:"Seçimini kendin için yapabilir, yardım alabilir, güvenli bir yazılı sınır veya pratik destek seçebilirsin."},result:{question:"Seçtiğin işi gerçekten yaptın mı?",observationPrompt:"Hangi seçimi yaptın? Hangi sorumluluğu korudun veya hangi koşula uydun?"},judgment:{primary:{id:"meaning-3-elective-cost-decision",scenario:"Murat hem gelirine hem bu akşamki aile konuşmasına önem veriyor. İş çevresiyle sohbet yarın aynı kişilerle tekrarlanacak. Bu akşam katılmamak ücretli vardiyayı etkilemiyor. Suçluluk her etkinliğe gitmesini zorluyor.",question:"Hangi seçim benimsediği nedeni, karşılayabileceği bir bedelle dener?",options:[{id:"meaning-3-attend-and-reschedule",text:"Bu akşam iş sohbetine katılıp sonraki vardiyadan sonraya aile konuşması planlayarak iki sözü de korumak.",feedback:"Zamanı değiştirmek iki değerli sözü koruyabilir. Burada aynı kişiler yarın da uygun ve gelir kaybı yok. Bu akşam seçtiği konuşmayı taşımak, bedeli daha düşük alternatif varken baskıya göre davranır."},{id:"endorsed-choice",text:"Zorunlu vardiyasını koruyup bu akşamki isteğe bağlı etkinliği reddetmek ve önem verdiği konuşma zamanını kullanmak.",feedback:"Gelirini korurken ve yarınki iş çevresi fırsatını tutarken benimsediği nedeni dener. Suçluluk kalabilir. Mesleki bedel farklı olsaydı başka seçim yerinde olabilirdi. Buradaki zaman ve koşullar bu kararı destekliyor."},{id:"meaning-3-split-evening",text:"İki yerde de görünür olmak için iş sohbetine kısaca katılıp ardından aile konuşmasını kısaltmak.",feedback:"Her iki fırsat da azsa bölmek işe yarayabilir. Burada iş sohbeti yarın tekrarlanıyor. Akşamı bölmek görünürlüğü korurken seçtiği dikkatten alır. Bunun yerine iki ayrı uygun fırsatı kullanabilir."}],bestOptionId:"endorsed-choice"}},carry:{takeaway:"Bir nedeni benimse. Bedelini kabul et ve sana uyan küçük bir seçimle onu dene.",followUp:{questionId:"meaning-3-return",question:"Bu seçimi yaptıktan sonra nedenini hâlâ benimsiyor musun? Hangi kısmı değişti?",observationPrompt:"Şimdi hangi nedeni benimsiyorsun? Emin olmadığın veya değiştirdiğin kısmı da söyle.",adjustmentPrompt:"Nedeni korumak, değiştirmek veya bedeli için destek almak arasından hangisi uygun?"}},goDeeper:{sections:[{heading:"Ailenden gelmesi, sana ait olmadığı anlamına gelmez",paragraphs:["Ryan ve Deci’nin öz belirleme kuramı, dışarıdan gelen nedenlerin kişinin kendi benimsediği nedenlere nasıl dönüşebileceğini anlatır. [M05] Aile sorumluluğu zor, ilişkilerle ilgili ve yine de senin olabilir. Keyif almak bir neden; birinin güvende olmasını önemsemek başka neden. Bu, baskı altındaki her sorumluluğu sağlıklı kılmaz. Yalnızca nereden geldiği, rahatsızlık veya takdir görme, seçimin sana ait olup olmadığını belirleyemez. Hangi nedenleri benimsediğine ve hangi baskıların seçimi sınırladığına bak.","“Kimse görmese ne yapardım?” isteğe bağlı düşünme sorusudur, doğrulanmış test değil. Suçluluk başkasının değerini taşıdığını, bedensel enerji de gerçek değerini bulduğunu kanıtlamaz. Neden diye sormak düşünmeye yardım edebilir. Tek doğru nedeni bulduğunu belgeleyemez. Karışık nedenlerinle bilinçli seçim yapabilirsin. Gerekli gelir ve bakımı koru. Kültürünle ve çevrenle ilgili sorumluluklarını da hesaba kat. Geri alınabilir, isteğe bağlı bir adım dene. Dersi bitirmek için kariyer, ilişki veya aile sorumluluğunu değiştirmek gerekmez."]},{heading:"Destek motivasyona yardım edebilir, kısa formun sınırı var",paragraphs:["Ntoumanis ve arkadaşları, 30.088 kişiyi içeren 73 sağlık çalışmasını birleştirdi. [M06] Programlar, kişinin benimsediği nedenlerle hareket etmesini ve sağlık davranışını ortalama olarak iyileştirdi. Sonuçlar oldukça farklıydı. 58 randomize, 15 yarı deneysel araştırma vardı. Kanıt, destek sunulan sağlık programlarına ait. Üç sorunun gizli doğru nedeni ortaya çıkardığını, dış nedenlerin her zaman zararlı olduğunu veya kısa ODA çalışmasının programları tekrarladığını göstermez.","ACT modeli de sürdürmek istediğin davranış özelliklerini somut işe bağlar. [M19] Burada bu bağlantı bir ODA uyarlaması. Birlikte sınanmış tedavi değil. Sonraki denemede belirli bir şey öğren: seçim sorumluluklarına uydu mu, nedenini hâlâ benimsiyor musun? Huzursuzluk kayıtta kalabilir. Baskı zorlamaya veya tehlikeye dönüşüyorsa uyum sağlamayı denemek yerine korunma ve destek önce gelir. Amacını değiştirebilir, kendine saklayabilir veya kimseye açıklama yapmak zorunda kalmadan ara verebilirsin."]}],sourceIds:["meaning-sdt","meaning-sdt-interventions","meaning-act-values"]}},{schemaVersion:2,revision:2,id:"meaning-4",courseId:"meaning",locale:"tr",title:"Acından ders çıkarmak zorunda değilsin",goal:"Seçtiğin amacı korumak için pratik bir istek, güvenli sınır veya kendine alan tanıyan tek iş seç.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Bu acıya anlam vermeye mi uğraşıyorsun? Önce yardım edilebilecek şeye bak. Anlam sorusu bekleyebilir.",reason:{id:"meaning-4-reason",label:"Bu amacı sürdürebilmek için hangi pratik düzenlemenin değişmesi gerekiyor?",kind:"text",maxLength:160,optional:!0,suggestions:["Tek bir bakım işini paylaşmak","İhtiyacım olan dinlenmeyi korumak","Yetkin birinden destek istemek"]},why:{id:"meaning-4-why",label:"Bu amacı sürdürebilmek için hangi pratik düzenlemenin değişmesi gerekiyor?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Geçmişteki olay değişmese de bugünkü düzen değişebilir. Hastalıkta kendiliğinden “Yapılacak hiçbir şey yok” sonucuna varma. Bakım ve değerlendirme gerekir. Frankl’ın kaçınılmaz acı karşısında tutum seçme fikri felsefi bir ihtimaldir. Acının iyi bir yanı olduğunu düşünmek zorunda değilsin. Başına gelenin acı ve haksız olduğunu söyleyerek de yardım istemeyi seçebilirsin.","Aynı denemene dön. Yük, bu işi sürdürmeyi güçleştiriyorsa çevresindeki desteği değiştir. Belirli tek iş için yardım iste, güvenli sınır koy veya gereken dinlenmeyi koru. Bunlar aynı amaca katkı sağlayabilir. Gerçekte ilettiğin isteği veya yaptığın değişikliği kaydet. Anlamlı hissetmen şart değil. Yanıt bekliyor olman da isteği yapmadığın anlamına gelmez."],example:{title:"Murat bakım yükünü paylaştırmak istiyor",text:"Cuma Murat, babasının ziyaretlerini düzenledikten sonra bitkin hissediyor. Bakmayı sürdürmek istiyor, ama her akşamını kaybetmek istemiyor. Mutfak masasında kardeşine cumartesi ulaşımını üstlenmesini isteyen bir mesaj gönderiyor. Yatma saatine kadar yanıt yok. Murat isteğini kaydediyor. Üzüntüsü sürüyor. Bundan bir hayat dersi çıkarmaya çalışmıyor. Yardım istemekle yardımın kabul edilmesini ayrı tutuyor."}},move:{invitation:"Amacını koru. Yardım edilebilecek tek bir yükü değiştirmek için adım at.",instructions:["Tutum çalışmasından önce hangi pratik değişikliğin mümkün olduğuna bak.","Belirli bir yardım iste veya kendini koruyan güvenli bir iş yap."],prompts:[],suggestions:{action:["Tek bir bakım işi için yardım iste","Güvenli sınır koy; uygun olduğun saatleri açıkça belirt","Yetkin birinden gereken desteği iste"],minimum:["Belirli yardım isteyen tek mesaj gönder","Tek bir sınırı açıkça söyle","Destek için bir kişiyle iletişim kur"],cue:["Akşam yemeğinden sonra ziyaretleri planlamadan önce","Sıradaki istek bana ulaştığında","Destek istemek için seçtiğim an geldiğinde"],place:["Mutfaktaki masamızda otururken","Güvenle konuşabildiğim mesaj grubumuzda","Ulaşabildiğim, mahremiyetimi koruyabildiğim yerde"],minutes:[2,5],fallback:["Destek verebilecek başka uygun birine sor","Sınırını açıklamadan koru ve yardım al","Erişebileceğim başka destek yolunu seç"],observation:["Gönderdiğim istek ve gelen herhangi bir yanıt","Gerçekte hangi pratik düzeni değiştirdiğim","Destek için gerçekten iletişim kurup kurmadığım"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"Tek bir bakım işi için yardım iste",minimum:"Belirli yardım isteyen tek mesaj gönder",minutes:2,cueHint:"Akşam yemeğinden sonra ziyaretleri planlamadan önce",placeHint:"Mutfaktaki masamızda otururken",obstacleHint:"İlk kişi yardım edemiyor veya onunla görüşmek güvenli değil.",fallbackHint:"Destek verebilecek başka uygun birine sor",observationHint:"Gönderdiğim istek ve gelen herhangi bir yanıt"},stopRule:"Krizde yerel kriz desteğine ulaş. ABD’de 988’i ara veya mesaj gönder. Acil tehlikede yerel acil yardım hizmetlerini kullan.",accessibleAlternative:"Yardım alarak isteğini iletebilir veya dinlenebilirsin. Umutsuzluk sürüyorsa veya günlük işler zorlaşıyorsa daha erken uzman desteği iste."},result:{question:"Seçtiğin pratik adımı gerçekten attın mı?",observationPrompt:"Ne istedin veya ne değiştirdin? Yanıt gelmediyse onu da söyle."},judgment:{primary:{id:"meaning-4-transport-constraint-decision",scenario:"Cumartesi hastaneye ulaşımı sağlamak Murat’ı bitkin bırakıyor. Kardeşi bu akşam kesinleşirse götürmeyi teklif etti. Ziyaretler kısalabilir ama ulaşım zorunlu. Ücretsiz yerel ulaşım hizmetinin cumartesi yeri yok.",question:"Hangi düzenleme şu anki yükü gerçekten ele alır?",options:[{id:"meaning-4-shorten-visits",text:"Başkasının zamanını ayarlamakla uğraşmadan yükünü azaltmak için cumartesi ziyaretini kısaltıp arabayla götürmeye devam etmek.",feedback:"Kısa ziyaret gücü koruyabilir ve işe yarayabilir. Ama onu bitkin bırakan zorunlu ulaşım işini değiştirmez. Önce var olan ulaşım teklifini kesinleştir, sonra sürdürebileceğin ziyaret süresini seç. İki yükü ayır."},{id:"meaning-4-community-route",text:"Kardeşinin teklifini kesinleştirmeden önce yerel ulaşım hizmetine iptalden açılabilecek yeri sorup gelecek yanıtı beklemek.",feedback:"Yerel ulaşım ileride yararlı olabilir. Cumartesi için kesin yer yok. Kardeşinin teklifiyse bu akşam yanıt bekliyor. Var olan yardımı, başka yerde iptal çıkmasına bağlamak yerine güvenceye al."},{id:"share-task",text:"Kardeşinden ulaşımı üstlenmesini isteyip ardından kendi gücüne ve koşullarına uyan bir ziyaret süresi seçmek.",feedback:"Zorunlu sağlık ulaşımını korurken değiştirilebilecek yük için var olan teklifi kullanır. Kabul edilmesini beklemeden isteği iletmiş olabilir. Yanıt gelmediyse kaydına bunu yaz. İstek ve anlaşma farklı olaylar."}],bestOptionId:"share-task"}},carry:{takeaway:"Tutumunun değişmesini bekleme. Destek alarak bugünkü düzeni değiştirmek için bir adım at.",followUp:{questionId:"meaning-4-return",question:"İsteğinden sonra hangi yardım veya pratik değişiklik oldu?",observationPrompt:"Hangi yanıt veya değişiklik oldu? Yanıt yoksa onu yaz.",adjustmentPrompt:"Kalan yük için hangi yardım, güvenli sınır veya dinlenme sana uygun?"}},goDeeper:{sections:[{heading:"Geçmişteki olay ve bugünkü imkânlar",paragraphs:["Frankl’ın açıklaması, gerçekten kaçınılamayan acı karşısında seçilebilecek bir tutumu içerir. [M17] Bu felsefi rehberliktir. Tutumun hastalığı iyileştirdiğinin veya travmayı yararlı kıldığının kanıtı değil. Ölüm veya geçmiş olay geri alınamaz. Bugünkü belirtiler, tedavi seçenekleri, sosyal destek ve gündelik düzen yine de değişebilir. Yardım seçeneklerine bakmadan bir tanının, başkasından gördüğün zararın veya destek eksikliğinin değiştirilemez olduğuna karar verme.","ACT modeli zor duygular sürerken seçtiğin biçimde davranmayı anlatır. [M19] Duyguyu yok etmek veya önlenebilir tehlikede kalmak zorunlu değil. Bakım vermeyi amaçlamaya devam edebilirsin. Yeni bir ziyaret yerine, ulaşımı paylaşmak için yardım isteyebilirsin. Dinlenmek, sınır koymak veya bilgi almak yerinde olabilir. Bunları koşullarında değerlendir. Yüce bir tutumun kanıtı sayma. Anlam sorusunu yanıtsız bırakabilirsin. ODA’ya acını anlatmak zorunda değilsin. İşin yararlı olup olmadığına bakmak için ayrıntı paylaşman gerekmez. Sadece bir yükü paylaşmayı istemen bile yeterince somut olabilir. Bunun için acının nedenini çözmen veya yaşadığını haklı göstermen gerekmiyor."]},{heading:"Destek almak için amaç bulman gerekmiyor",paragraphs:["NIMH rehberi depresyon belirtilerini, uzman değerlendirmesini ve tedavi seçeneklerini anlatır. [M20] Süren umutsuzluk, çökkünlük, ilgi kaybı veya günlük işleri yapmakta güçlük destek gerektirir. Tek başına anlam kaybı tanı değildir. Kurs bu değerlendirmeyi yapamaz. Belirtiler herhangi bir süre eşiğine ulaşmadan yardım isteyebilirsin. Doktora veya ruh sağlığı uzmanına ulaşmak için kursu bitirmeyi ya da değerler sorusuna cevap bulmayı bekleme. Yardım daha erken de istenebilir.","İntihar düşüncelerinde veya duygusal krizde bulunduğun yerdeki kriz desteğine ulaş. ABD’de 988’i arayabilir veya mesaj gönderebilirsin. Acil tehlikede yerel acil yardım hizmetlerini kullan. Krizde gereken adım yeni bir düşünme alıştırması değil, insandan yardım almaktır. Kriz dışında isteğin küçük ve belirli kalabilir: bakım işi, toparlanma zamanı veya randevu. Yanıt yoksa bunu kaydet. İlk yol kullanılamıyorsa başka uygun yola bak. Engeli, hayatında anlam bulamadığının kanıtı sayma."]}],sourceIds:["meaning-frankl","meaning-act-values","meaning-support"]}},{schemaVersion:2,revision:2,id:"meaning-5",courseId:"meaning",locale:"tr",title:"Düşlediğin geleceğin küçük bir parçasını bugün yap",goal:"Sade bir gelecek sahnesinden, seçtiğin amaca katkı sağlayan somut bir iş çıkar.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Geleceğin zihninde çok net. Onun hangi küçük parçasını bu hafta gerçekten yapacaksın?",reason:{id:"meaning-5-reason",label:"Bu geleceğin haftana sığması için şimdi hangi koşulun değişmesi gerekiyor?",kind:"text",maxLength:160,optional:!0,suggestions:["İlişkime gerçekten zaman vermek","İşe yarayan tek bir şey üretmek","Bütçeme ve gücüme göre davranmak"]},why:{id:"meaning-5-why",label:"Bu geleceğin haftana sığması için şimdi hangi koşulun değişmesi gerekiyor?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Geleceği yazma çalışmalarında iyimserlik ve olumlu duygular için kanıt, depresyon ve olumsuz duyguların azalmasına ilişkin kanıttan daha açık. Hayal ettiğin hayatın gerçekleşeceği gösterilmiş değil. Kısa bir sahne, denemen için hazırlık olabilir. Bir iş yaptığının kanıtı değildir. Geleceği düşünmekle o geleceğe katkı veren davranışı yapmak ayrı olaylardır.","İşine yarıyorsa yakın gelecekte sıradan bir gün düşün. Aynı amacını koru. Sonraki görünür parçasını seç: gerçek konuşma, işe yarayan cümle veya belirli istek. Engeline ve imkânlarına bak. Sonra o parçayı yap. Geleceği hayal etmek yardım etmiyorsa atla. Bunun yerine işi doğrudan seçebilirsin. Hayal çalışması, işe başlamak için zorunlu şart değil."],example:{title:"Murat sıradan bir salı hayal ediyor",text:"Cumartesi kahvaltısında Murat, bakım işlerinin paylaşıldığı ve evde yardım ettiği bir salıyı düşünüyor. Bu sahne hazırlık. Tek bir parçasını işe dönüştürüyor: kızının okul maketi için anlaşılır bir etiket yazmak. Mutfak masasında etiketi bitiriyor. Maketin kalanı hâlâ çalışma istiyor. Murat hayal ettiği günle yaptığı etiketi ayrı tutuyor. Bugün gerçekten ortaya çıkan parça bu."}},move:{invitation:"Düşündüğün geleceğin bir parçasını, bugünkü küçük adımında hayata geçir.",instructions:["İşe yarıyorsa kısa bir sahne düşün. Bu hazırlıktır.","Gerçek bir engeli belirt, sonra ilgili tek parçayı yap."],prompts:[],suggestions:{action:["Proje için işe yarayan tek cümle yaz","Proje için kullanılabilecek tek taslağı çiz","İlgili bir konuda geri bildirim isteyen mesaj gönder"],minimum:["Kullanılabilecek tek bir cümle yaz","İşe yarayan tek taslağın ana hatlarını çiz","Belirli bir konuda tek geri bildirim sorusu gönder"],cue:["Projemi açıp başına geçtiğimde","Projemde ana hatları çizmem gerektiğinde","Çalışmaya ayırdığım zaman geldiğinde"],place:["Her zamanki çalışma yerimde","Mutfaktaki masamızda çalışırken","Güvenle konuşabildiğim mesaj grubumuzda"],minutes:[2,5],fallback:["Amacıma katkı sağlayan daha küçük parça seç","Çizmek yerine sözcüklerle tarif et","İhtiyaç duyduklarıma ulaşmak için yardım iste"],observation:["Gerçekte hangi parçayla katkıda bulunduğum","Engelin neyi değiştirdiği","Gönderdiğim istek ve gelen herhangi bir yanıt"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"Proje için işe yarayan tek cümle yaz",minimum:"Kullanılabilecek tek bir cümle yaz",minutes:2,cueHint:"Projemi açıp başına geçtiğimde",placeHint:"Her zamanki çalışma yerimde",obstacleHint:"Hayal ettiğim hâli, elimdeki imkânları aşıyor.",fallbackHint:"Amacıma katkı sağlayan daha küçük parça seç",observationHint:"Gerçekte hangi parçayla katkıda bulunduğum"},stopRule:"Gelecek sade ve güvenli kalsın. Sıkıntı artarsa hayali bırak. Bedeli ağır sözler verme.",accessibleAlternative:"İşi doğrudan seçebilir, hayal etmek yerine sözcükleri kullanabilir veya yardım alarak katkıda bulunabilirsin."},result:{question:"Seçtiğin parçayı gerçekten ürettin mi?",observationPrompt:"Denemenden sonra gerçekte ne ortaya çıktı veya ne oldu?"},judgment:{primary:{id:"meaning-5-feedback-opening-decision",scenario:"Bir tasarımcının bitmiş bir örneği var. İş arkadaşı bu akşam geri bildirim verebilir. İstediği gelecek birlikte çalışmak. Daha güçlü ekipmanı gelecek hafta ödünç alabilir, ama bu örnek için gerekmiyor.",question:"Hangi adım, elindeki imkânlarla seçtiği amacı dener?",options:[{id:"meaning-5-prepare-presentation",text:"Örneğin sunumunu bu akşam iyileştirip ardından iş arkadaşının sonraki uygun fırsatında geri bildirim istemek.",feedback:"Daha iyi sunum örneği anlaşılır kılabilir. Bu örnek bitmiş ve geri bildirim fırsatı bu akşam. Şimdi belirli bir soru gönder. Sunumu düzeltmen gerekip gerekmediğine yanıta göre karar verebilirsin."},{id:"share-sample",text:"Bütçesini koruyup elindeki bitmiş örneği göndermek ve onun hakkında belirli tek bir geri bildirim sorusu sormak.",feedback:"Elindeki imkânlarla amacına uygun davranışı dener. Geleceği yazmakla hedefe ulaşmak farklı sonuçlar. Kusursuz olmayan yanıt da sonraki denemeye bilgi sağlar. Gönderdiği soru ve aldığı yanıt ayrı kayıtlardır."},{id:"meaning-5-borrow-equipment",text:"Geri bildirim istemeden önce daha güçlü bir örnek hazırlamak için gelecek hafta ödünç alacağı ekipmanı beklemek.",feedback:"Ekipman gerekiyorsa ödünç almak bütçeyi koruyabilir. Bu örnek için gerekmiyor ve iş arkadaşı şimdi uygun. Gerekleri büyütmeden önce elindeki örnekle birlikte çalışmayı dene. Ulaşılabilir fırsatı kullanabilirsin."}],bestOptionId:"share-sample"}},carry:{takeaway:"Gelecek sahnesi hazırlıktır. Bugün o amaca katkı sağlayan gerçek bir parçayı yap.",followUp:{questionId:"meaning-5-return",question:"Yaptığın iş, düşündüğün gelecekle bu haftan arasında somut bir bağlantı kurdu mu?",observationPrompt:"Hangi parça ortaya çıktı? Amacına nasıl katkı sağladı veya nerede yetmedi?",adjustmentPrompt:"Sonraki parça hangi eksik kaynağı veya gerçek engeli ele almalı?"}},goDeeper:{sections:[{heading:"Geleceği yazmak hakkında gerçekte ne bulundu?",paragraphs:["Carrillo ve arkadaşları, 2.909 kişiyi kapsayan 29 araştırmayı birleştirdi. [M09] Sonuçlar iyi oluş, iyimserlik ve olumlu duygularda ortalama iyileşmeleri destekledi. Olumsuz duygu ve depresyon belirtilerindeki azalmalar gösterilmedi. Güven aralıkları sıfırı içeriyordu. Depresyonu yalnızca üç araştırma değerlendirdi. Olumlu görünen ortalama, belirsiz tahmini kesinleştiremez. Çalışmalar çoğunlukla kısa vadeli sonuçları ölçtü, farklı yazma yöntemleri kullandı. Daha çok anlam veya gelecekte gerçek başarı gösterilmedi.","King’in ilk gelecek yazma görevinde, 81 üniversite öğrencisi dört yazma koşuluna rastgele atandı. Çalışma art arda dört gün, her gün 20 dakikaydı. [M10] Buradaki kısa, yakın geleceğe ve değerlerine bağlı sahne, süreyi ve amacı değiştirir. Bir ODA uyarlaması; ilk yöntem değil. İsteğe bağlı uzun yazıya ayrıca zaman ayır. İdeal beş yıllık hayat yazmak veya kendini onunla karşılaştırmak zorunda değilsin. Sıradan bir ihtimal, sonraki pratik işi seçmeye yetebilir."]},{heading:"Geleceği bugünün engeliyle birlikte düşün",paragraphs:["Zihinsel karşılaştırmayı “Şu olursa bunu yaparım” planıyla birleştirmek, yapılabilir isteği, istediğin sonucu, bugünkü engeli ve yanıtı birlikte ele alır. Wang ve arkadaşları 21 makaleden, 15.907 kişiyi kapsayan 24 bağımsız araştırmayı inceledi. [M13] Hedefe ulaşmada küçük ortalama etki bulundu: g = 0,336, yüzde 95 güven aralığı 0,229 ile 0,443. Yayın yanlılığına göre düzeltme daha küçük tahmin verdi. Uygulama ve kalite farkları kesinliği sınırlar. Herkes için kanıtlanmış tek süre yok.","Bu kurs, gelecek sahnesini aynı amacın ve somut işinle birleştirir. Bu birleşik uygulama araştırmalarda sınanmadı. Eksik kaynak, bakım sorumluluğu veya güvensiz ortam, içsel zayıflık değil gerçek koşuldur. Pratik yanıt daha küçük bir ürün, yardım isteği veya başka fırsat olabilir. Ortaya çıkan işi veya görüşmeyi sahneden ayrı kaydet. Geleceği hayal etmek baskı veya sıkıntı ekliyorsa çıkar. Doğrudan seçtiğin işle devam edebilirsin. Hayalin hoş görünmesi, gereken kaynakları kendiliğinden sağlamaz."]}],sourceIds:["meaning-carrillo","meaning-best-possible-self","meaning-mental-contrasting"]}},{schemaVersion:2,revision:2,id:"meaning-6",courseId:"meaning",locale:"tr",title:"Plan yine aksadı mı? İşe yarayanı tut",goal:"Kayıtlarından yararlan. Aynı değerine bağlı denemeyi gelecek hafta tekrarlamayı, değiştirmeyi veya bırakmayı seç.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Plan yine mi aksadı? Sırada ne olacağını gerçekten yaptığın denemelere göre seç.",reason:{id:"meaning-6-reason",label:"Hangi işi bu haftanda yeniden denemeye değer buluyorsun?",kind:"text",maxLength:160,optional:!0,suggestions:["Yararlı küçük bir işi sürdürmek","İşe yaramayan başlama anını değiştirmek","Sürdürebileceğim bir amacı korumak"]},why:{id:"meaning-6-why",label:"Hangi işi bu haftanda yeniden denemeye değer buluyorsun?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["İşi planlamakla yapmak farklı şeyler. Araştırmalar belirli bir başlama anına bağlanan planları ve ilerlemeyi takip etmeyi, hedefe ulaşmak için ortalama olarak destekler. Hiçbiri günlük bir işin anlam duygusunu artırdığını göstermez. Denemende olanları, sana hissettirdiklerinden ayrı tut. Neyi planladığınla neyi gerçekten yaptığını da ayrı ayrı gör.","Aynı amacını ve denemelerinin kayıtlarını gözden geçir. Hangi fırsat oluştu? Hangi küçük adım amacına katkı sağladı? Gelecek hafta tekrarlayacağın veya değiştireceğin tek şeyi seç. Yararlı işi tut, fazladan rutinleri bırak. Kaçan fırsat bilgi verir. Alışkanlığın son tarihi veya değerlerin hakkında hüküm değildir. Destek, dinlenme ve zarar veren planı bırakmak seçeneklerin arasında kalsın."],example:{title:"Murat kayıtlarına göre planlıyor",text:"Pazar mutfak masasında Murat kayıtlarını okuyor: iki konuşma, oluşmayan bir fırsat, yanıtsız bir yardım isteği. Akşam yemeği sonrası iki dakika, geç akşamdan daha iyi uymuş. Kızına maketi yeniden sorup yanıtını dinliyor. Gelecek hafta aynı başlama anını koruyor. Ziyaretler bu zamanı kaplarsa yeniden destek isteyecek. Kaydın gösterdiği koşulu kullanıyor. Konuşmanın yine olacağını garantilemiyor."}},move:{invitation:"Kayıtlarını kullan. Gelecek hafta işe yarayan tek bir işi sürdür.",instructions:["Gerçekte oluşan fırsatları ve denediğin küçük adımları karşılaştır.","Tek bir koşulu değiştir, sonra sıradaki denemeyi yap."],prompts:[],suggestions:{action:["İşe yarayan dinleme adımımı yeniden dene","İşe yarayan proje katkımı yeniden yap","Kayıtlarımın gösterdiği destek isteğini gerçekten ilet"],minimum:["Tek bir yanıtı dikkatimi vererek dinle","Kullanılabilecek tek bir cümle yaz","Belirli bir destek isteyen tek mesaj gönder"],cue:["Akşam yemeğinden sonra birlikte oturduğumuzda","Projede denediğim başlama anı geldiğinde","Sıradaki bakım düzenlemesini yapmadan önce"],place:["Mutfaktaki masamızda","Her zamanki çalışma yerimde","Güvenle konuşabildiğim mesaj grubumuzda"],minutes:[2,5],fallback:["Denediğim daha küçük adımı kullan","Başka bir gerçekçi fırsatı seç","Destek al veya bu plana ara ver"],observation:["Yaptığım iş ve başlama anının oluşup oluşmadığı","Değiştirdiğim koşulun neye imkân verdiği","Küçük adımın hâlâ amacıma katkı sağlayıp sağlamadığı"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}]},suggested:{action:"İşe yarayan dinleme adımımı yeniden dene",minimum:"Tek bir yanıtı dikkatimi vererek dinle",minutes:2,cueHint:"Akşam yemeğinden sonra birlikte oturduğumuzda",placeHint:"Mutfaktaki masamızda",obstacleHint:"Eski zaman aralığı artık sorumluluklarıma uymuyor.",fallbackHint:"Denediğim daha küçük adımı kullan",observationHint:"Yaptığım iş ve başlama anının oluşup oluşmadığı"},stopRule:"Güvenlik, bakım veya gereken toparlanmayla çelişen planları değiştir ya da bırak.",accessibleAlternative:"Yeni rutin eklemeden, yapabileceğin tek işi koruyabilir, yardım isteyebilir veya dinlenmeyi seçebilirsin."},result:{question:"Sıradaki en küçük adımı gerçekten yaptın mı?",observationPrompt:"Gerçekte ne yaptın? Seçtiğin başlama anı oluştu mu?"},judgment:{primary:{id:"meaning-6-tested-opening-decision",scenario:"Murat’ın geç akşam planı, ziyaretler uzadığı için iki kez olmadı. Akşam yemeği zamanı iki kısa konuşmaya elverdi. Hafta sonu uygunluk belirsiz. Gelecek hafta görüşmek istiyor ve akşam yemeği sonrası fırsatı yine kullanabilir.",question:"Gelecek hafta için hangi plan bu kayıtları daha iyi kullanır?",options:[{id:"meaning-6-earlier-night",text:"Daha uzun, bölünmeyen konuşmayı korumak için akşam görüşmesini otuz dakika daha erkene taşımayı denemek.",feedback:"Erken saat uzun konuşmayı koruyabilir. Ama kayıtlar ziyaretlerin uzadığını gösteriyor. Bu değişikliğin onları önleyeceği bilinmiyor. Önce gerçekten konuşmayı mümkün kılan akşam yemeği sonrası fırsatı yeniden dene. Gözlenmiş koşulu kullan."},{id:"meaning-6-weekend-conversation",text:"Hafta içi ziyaretleriyle çakışmayı önlemek için daha uzun bir konuşmayı hafta sonuna ayırıp planlamak.",feedback:"Saat üzerinde anlaşırlarsa hafta sonu konuşması değerli olabilir. Burada uygunluk belirsiz. Gelecek hafta denenmiş akşam yemeği sonrası küçük adımı koru. Gerçek fırsat çıktığında daha uzun konuşmayı ayrıca ayarla."},{id:"tested-cue",text:"İlişki amacını koruyup akşam yemeği sonrası küçük adımı kullanmak ve başka değişiklik yapmadan sonraki denemeyi kaydetmek.",feedback:"Seçtiği işi mümkün kılan fırsatı tekrarlar. Yeni konuşmayı garantilemez. Başlama anının oluşup oluşmadığını ve ne olduğunu kaydet. Sonra daha fazla destek veya değişiklik gerekip gerekmediğine karar ver."}],bestOptionId:"tested-cue"}},carry:{takeaway:"Tek amacı ve işe yarayan işi koru. Gerçekte olanı kaydederek sonraki denemeyi iyileştir.",followUp:{questionId:"meaning-6-return",question:"Kayıtlarından seçtiğin koşul sonraki işi yapmana yardım etti mi? Hangi kısmı etkiledi?",observationPrompt:"Başlama anı oluştu mu? Bu koşul neyi mümkün kıldı, ne olmadı?",adjustmentPrompt:"Aynı koşulu tekrarlamak, değiştirmek, destek almak veya bırakmak arasından hangisi uygun?"}},goDeeper:{sections:[{heading:"Planlama ve takip, davranış hakkında bilgi verir",paragraphs:["Gollwitzer ve Sheeran, 8.461 kişinin katıldığı 94 bağımsız testi birleştirdi. [M11] Belirli durumda belirli işi yapma planları, farklı ortam ve araştırmalarda hedefe ulaşmayı ortalama olarak destekledi. Harkin ve arkadaşları 138 randomize takip araştırmasını inceledi. [M14] Birleştirilmiş hedefe ulaşma tahmini d = 0,40, yüzde 95 güven aralığı 0,32 ile 0,48 idi. Küçük araştırmalarda asimetri bulundu. Duyarlılık analizi d = 0,19 tahmin etti. Bunlar hedefe ulaşma sonuçları; tatmin garantisi değil.","Bu derlemeler ODA’nın kaydını ve ertesi gün yeniden bakma zamanını doğrulamadı. Bu adımların amacı, verdiğin sözü gerçek denemeyle karşılaştırıp daha uygun adımı seçmek. Herkese açık takip gerekmiyor. İstersen özel ayrıntıları ODA dışında tut. Geleceğe dair planı gerçekleşmiş sayma. Sonucu bildirilmemiş bir denemede ne olduğu henüz bilinmiyor. İşe yarayan küçük adımı büyütmeden tekrarlayabilirsin. Pratik destek isteği veya dinlenme planı aynı amaca başka bir zorlayıcı işten daha uygun katkı sağlayabilir."]},{heading:"Alışkanlık tahmini bir son tarih değil",paragraphs:["Lally ve arkadaşları, 84 günlük gözlem araştırmasında 96 kişiyi takip etti. [M15] Katılımcılar günlük başlama anları olan yeme, içme veya hareket davranışları seçti. Modellenen otomatikleşme çok farklı hızlarda arttı. Bilinen 66 gün ortancası ve 18–254 gün aralığı, verilere uyan eğrilerle hesaplanan tahminleri anlatır. Uzun tahminler gözlem süresini aşar. İşinin son tarihi veya değerlerin otomatikleştiğinin kanıtı değildir. Birkaç kaçan günün etkisizliğini göstermez. Tek fırsatı kaçırmanın ölçülen etkisi azdı.","Bu denemede yiyecekle ilgili olmayan, değerine bağlı bir iş yapıyor ve ertesi gün olanları gözden geçiriyorsun. Bu araştırma yöntemi değil, uyarlama. Kayıtlarında işe yaradığını gördüğün şeyleri sürdür: uygun bir başlama anı, yararlı küçük adım ve engelle karşılaşınca yapacağın iş. Yardım etmeyen alıştırmayı çıkar. Bölünen haftayı her beklentiyi ikiye katlayarak düzeltme. Sonraki yapılabilir fırsatı seç, gerekirse yardım iste. Plan değiştiğinde geçmiş kaydı olduğu gibi koru. Yeni plan, eski denemede olanı değiştirmesin."]}],sourceIds:["meaning-planning","meaning-monitoring","meaning-habits"]}}],m=[{id:"meaning-1",practice:["Tek katkı veya ilişki seç. Zorlukları düşünmek isteğe bağlı.","İşe yarayan bir iş ve güvenli bir fırsat belirle.","Seçtiğin işi yap, sonra ne olduğunu kaydet."],correct:1,photo:{id:"1469474968028-56623f02e42e",alt:"Sisli vadi üzerindeki kayada tek başına duran bir kişi"}},{id:"meaning-2",practice:["Seçtiğin aynı amacı ve işi kullan.","Acil olmayan tek işi erteleyerek uygun zamana yer aç.","İşe yarayan küçük adımı yap. Hangi işin beklediğini kaydet."],correct:2,photo:{id:"1470071459604-3b5ec3a7fe05",alt:"Yeşil kayalıklar ve vadinin üzerinde süzülen bulutlar"}},{id:"meaning-3",practice:["Karışık nedenlere yer bırakırken benimsediğin bir nedeni söyle.","Gerekli sorumlulukları koru. Geri alınabilir, isteğe bağlı tek işi ertele.","İşi yapıp seçimini kaydet. Suçluluğuna puan vermek gerekmiyor."],correct:0,photo:{id:"1447752875215-b2761acb3c5d",alt:"Yeşil ormanın içinden geçen ahşap yaya köprüsü"}},{id:"meaning-4",practice:["Hangi pratik yardımın veya korunmanın mümkün olduğuna bak.","Belirli bir istek, güvenli sınır veya gereken dinlenmeyi seç.","Anlam veya iyi taraf bulmayı şart koşmadan seçtiğin adımı at."],correct:2,photo:{id:"1519681393784-d120267933ba",alt:"Gece karlı dağların üzerinde parlayan yıldızlar"}},{id:"meaning-5",practice:["İstersen yakın gelecekte sade bir sahne düşün. Bu hazırlıktır; ilk araştırmadaki yazma yöntemi değil.","Gerçek bir engel seç ve karşılaştığında ne yapacağını belirle.","Amacına katkı sağlayan tek parçayı yap. Sahneyi ve işi ayrı kaydet."],correct:1,photo:{id:"1501785888041-af3ef285b470",alt:"Dağlarla çevrili sakin bir göl"}},{id:"meaning-6",practice:["Aynı amacın için gerçekten yaptığın denemeleri karşılaştır.","Gelecek hafta tekrarlayacağın veya değiştireceğin tek koşulu seç.","Yararlı küçük adımı dene. Başlama anını ve yaptığın işi kaydet."],correct:1,photo:{id:"1472214103451-9374bd1c798e",alt:"Yumuşak ışıkta ağaçların olduğu yeşil çayır"}}],s={id:"meaning",title:"Günün dolu, önemsediğin şeye sıra yok mu?",subtitle:"6 ders. Seçtiğin amaç için küçük adımlar at, olanları kaydet ve haftana uyan bir plan yap.",description:"Dikkatini vermeye değer bir ilişki veya katkı seç. Küçük bir iş dene, seçimlerinin bedeline bak ve gerçekte olana göre değiştir.",scope:"Günleri dolu ama yönünü kaybetmiş hisseden, yol ayrımında olan veya günlerini önem verdiği şeylere göre yaşamak isteyen yetişkinler için. Hayatın ve seçimlerin üzerine düşünmeni sağlayan bir eğitimdir. Terapi veya tedavi değildir. Boşluk veya umutsuzluk sürüyorsa ya da günlük işleri yapmak zorlaşıyorsa bir doktora veya ruh sağlığı uzmanına başvur. Daha erken destek de isteyebilirsin. İntihar düşüncelerinde veya duygusal krizde bulunduğun yerdeki kriz desteğine ulaş. ABD’de 988’i arayabilir veya mesaj gönderebilirsin. Acil tehlikede yerel acil yardım hizmetlerini kullan.",outcome:"Sorumluluklarını koruyan bir deneme, yaptıklarının kaydı ve gelecek hafta için bir plan.",photo:{id:"1500530855697-b586d89ba3ee",alt:"Açık tepeler arasından ufka doğru kıvrılan bir yol"},lang:"tr",lessons:k.map((a,t)=>{const n=m[t],e=a.judgment.primary,r=e.options.find(i=>i.id===e.bestOptionId),l=e.options.filter(i=>i.id!==e.bestOptionId).map(i=>i.text);return l.splice(n.correct,0,r.text),{...n,schemaVersion:2,v2:a,title:a.title,minutes:a.minutes.learning,goal:a.goal,reading:a.idea.paragraphs,deeper:a.goDeeper.sections,example:a.idea.example,reflection:a.direction.reason.label,question:`${e.scenario} ${e.question}`,options:l,feedback:r.feedback,takeaway:a.carry.takeaway,sources:a.goDeeper.sourceIds}})};export{s as COURSE,k as LESSONS_V2,d as SOURCES};
